// The app's own commands get an explicit permission each (`allow-<command>`, generated by tauri-build from
// this list). capabilities/default.json grants exactly those and nothing else, so a command that is added to
// the handler but not listed here and in the capability is refused by Tauri's ACL (RC3 least privilege).
// This list, the `generate_handler!` list in src/main.rs and the capability file are compared by
// tests/test_launcher_tauri_config.py.
const APP_COMMANDS: &[&str] = &[
    "start_native",
    "stop_native",
    "open_ui",
    "legacy_service_warning",
    "device_report",
    "docker_available",
    "advanced_docker_up",
    "advanced_docker_down",
    "advanced_docker_purge",
    "about_info",
    "about_text",
];

fn main() {
    tauri_build::try_build(
        tauri_build::Attributes::new().app_manifest(tauri_build::AppManifest::new().commands(APP_COMMANDS)),
    )
    .expect("failed to run tauri-build");
}
